import{_ as e,o as a,c as s,a3 as d}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Roadmap | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/roadmap"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/roadmap"}]]},"headers":[],"relativePath":"xclang/design/roadmap.md","filePath":"en/xclang/design/roadmap.md","lastUpdated":1791525642000}'),n={name:"xclang/design/roadmap.md"};function r(i,t,o,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>What xclang supports today, and the status of everything it does not. Every item that no release carries has one row here, with one status word. Other pages link to that row instead of restating the status. Nothing here has a date. What each release changed is in the <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><table tabindex="0"><thead><tr><th>status</th><th>meaning</th></tr></thead><tbody><tr><td><span class="status-badge ok">Supported</span></td><td>In a release.</td></tr><tr><td><span class="status-badge warn">Unreleased</span></td><td>On <code>main</code> and tested by CI, but no release carries it.</td></tr><tr><td><span class="status-badge note">Planned</span></td><td>Decided, and in no release yet. It may be in progress on a branch.</td></tr><tr><td><span class="status-badge note">In research</span></td><td>Wanted. Whether it can be done well is still open.</td></tr><tr><td><span class="status-badge note">Considered</span></td><td>Wanted. Its form or its cost is still open.</td></tr><tr><td><span class="status-badge off">Not planned</span></td><td>Out of scope by design.</td></tr></tbody></table><h2 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h2><p>xclang&#39;s vision is what rustup, cross-rs and cargo-zigbuild do for Rust, for clang: one compiler for every target.</p><ul><li>The common targets come with the toolchain, as the six of today do.</li><li>Every other target is an archive of its own, fetched when a build needs it: its sysroot, its prebuilt runtimes and its config file.</li><li>Vendor SDKs that no one may redistribute (Apple&#39;s, Microsoft&#39;s) are fetched from the vendor by the user, who accepts their license. xclang never redistributes them.</li><li>Runtimes can also be built from source on demand, for options the prebuilt ones lack.</li></ul><p>Today, the first and the third are in a release: the six targets, and since 23.1.2.7 Microsoft&#39;s and Apple&#39;s SDKs, which the user fetches with the <a href="#xclang-command"><code>xclang</code> command</a>. The rest is planned, in research or considered, item by item, in the tables below.</p><p>Every target keeps the <a href="./hermeticity">hermeticity</a> rule. A program depends at run time only on the libraries of its OS that cannot be redistributed, and links everything else statically.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p>A target&#39;s tier says how it is tested (<a href="./../reference/targets#tiers">tiers</a>). For the targets here, tier 1 can also mean a runner that runs the target&#39;s programs: Windows x64 runs x86 programs, wasmtime WebAssembly ones. A tier 3 target may get its runtimes <a href="#libc-on-demand">built on demand</a> instead of prebuilt. &quot;The user (SDK)&quot; means the target needs a vendor SDK that the user fetches, accepting its license.</p><table tabindex="0"><thead><tr><th>target</th><th>C runtime</th><th>from</th><th>tier</th><th>status</th></tr></thead><tbody><tr><td><a id="linux"></a>Linux x64, arm64</td><td>glibc 2.17</td><td>the toolchain</td><td>1</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="mingw"></a>Windows x64, arm64 (MinGW)</td><td>mingw-w64, UCRT</td><td>the toolchain</td><td>1</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="macos"></a>macOS arm64, x64, from macOS hosts</td><td>Apple&#39;s SDK</td><td>Xcode</td><td>1</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="msvc"></a>Windows x64, arm64 (MSVC), with their sanitizers</td><td>Microsoft&#39;s CRT and STL, Windows SDK</td><td>the user (SDK)</td><td>1</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="macos-any-host"></a>macOS arm64, x64, from Linux and Windows hosts</td><td>Apple&#39;s SDK</td><td>the user (SDK)</td><td>1</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="musl"></a>Linux x64, arm64 (musl), in every archive</td><td>musl 1.2.6, static</td><td>the toolchain</td><td>1</td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a id="windows-x86-msvc"></a>Windows x86 (MSVC)</td><td>Microsoft&#39;s CRT and STL, Windows SDK</td><td>the user (SDK)</td><td>1</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="windows-7"></a>Windows 7 and XP (MSVC)</td><td>Microsoft&#39;s CRT, static, with YY-Thunks</td><td>the user (SDK)</td><td>3</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="windows-x86-mingw"></a>Windows x86 (MinGW)</td><td>mingw-w64, UCRT</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="arm64ec"></a>Windows arm64ec</td><td>Microsoft&#39;s ARM64EC libraries</td><td>the user (SDK)</td><td>3</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="msvcrt"></a>Windows (MinGW) on msvcrt, before Windows 10</td><td>msvcrt</td><td></td><td></td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="glibc-newer"></a>Linux x64, arm64 with a newer glibc</td><td>glibc 2.28</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="linux-architectures"></a>Linux x86</td><td>glibc 2.17</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux armv7 (hard float)</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux riscv64</td><td>glibc 2.31</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux ppc64le, s390x</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux loongarch64</td><td>glibc 2.36</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="musl-architectures"></a>Linux riscv64, armv7 (musl)</td><td>musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="wasm"></a>WebAssembly (<code>wasm32-wasip1</code>, <code>wasm32-wasip2</code>)</td><td>wasi-libc</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="android"></a>Android arm64, x64, armv7</td><td>bionic</td><td>the user, from the NDK (SDK)</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="openharmony"></a>OpenHarmony arm64</td><td>OpenHarmony&#39;s musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="freebsd"></a>FreeBSD x64, arm64</td><td>FreeBSD 14&#39;s libc</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="bsd"></a>OpenBSD, NetBSD</td><td>their libc</td><td>xclang</td><td>3</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="bare-metal"></a>Bare metal: Arm Cortex-M, -R, -A, AArch64, RISC-V</td><td>picolibc</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="ios"></a>iOS, tvOS, watchOS, visionOS, their simulators</td><td>Apple&#39;s SDKs</td><td>the user, from full Xcode (SDK)</td><td>3</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="emscripten"></a>Emscripten</td><td>Emscripten&#39;s own</td><td>emsdk</td><td></td><td><span class="status-badge off">Not planned</span></td></tr></tbody></table><p>What sets these targets apart:</p><ul><li><strong>MSVC targets.</strong> First-class targets, as the MinGW ones are, since 23.1.2.7. The default C runtime is Microsoft&#39;s &quot;hybrid CRT&quot;: the VC runtime and the STL static, UCRT dynamic. xclang builds their compiler-rt: the builtins, the profile runtime and UBSan, and for x64 AddressSanitizer, whose runtime is a DLL, and libFuzzer. The MSVC and Windows SDK versions are pinned to ones the shipped clang accepts, and the user fetches them with the <a href="#xclang-command"><code>xclang</code> command</a>, which every toolchain archive carries (<a href="./windows#msvc-targets">Windows</a>). CMake builds them, and so does the Bazel module, unreleased (<a href="#msvc-bazel">below</a>).</li><li><strong>macOS from any host.</strong> Since 23.1.2.7. Apple&#39;s macOS SDK is in the Command Line Tools package on Apple&#39;s update servers, and needs no Apple ID to download. The user fetches it with the <a href="#xclang-command"><code>xclang</code> command</a> into the toolchain, whose config files then use it on Linux and Windows hosts; on macOS, Xcode&#39;s SDK stays the one in use. The programs are those of a macOS host: xclang&#39;s libc++ linked in, ld64.lld, dSYMs, the sanitizers (<a href="./macos#the-sdk-on-linux-and-windows-hosts">macOS</a>). CMake builds them, and so does the Bazel module, unreleased (<a href="#macos-any-host-bazel">below</a>).</li><li><strong>musl.</strong> Static programs that take nothing from the system they run on, in every archive from 23.1.2.10 on, as the six are: musl built by xclang, libc++ and every runtime linked in, UBSan the only sanitizer, as the others need dynamic linking (<a href="./../reference/targets#musl-targets">targets</a>). CMake, Bazel and cargo build them.</li><li><strong>A newer glibc.</strong> The same targets for programs that need what glibc 2.17 lacks, such as <code>-static-pie</code> and newer functions, with the same runtimes.</li><li><strong>Other Linux architectures.</strong> Each gets the oldest glibc it has; riscv64 and loongarch64 have nothing as old as 2.17. Their sanitizers are the ones compiler-rt supports on them.</li><li><strong>WebAssembly.</strong> <code>wasm32-wasip2</code> links with <code>wasm-component-ld</code>, which each host&#39;s toolchain needs to carry. C++ exceptions are opt-in.</li><li><strong>Android.</strong> The NDK&#39;s sysroot, with xclang&#39;s static libc++ in the NDK&#39;s ABI namespace (<code>__ndk1</code>).</li><li><strong>iOS and Apple&#39;s other devices.</strong> Their SDKs come only with full Xcode, downloaded with an Apple ID; xclang cannot remove that limit. Their runtimes are likely to be <a href="#libc-on-demand">built on demand</a>.</li><li><strong>Windows 7 and XP.</strong> The MSVC target with the CRT linked statically, and <a href="https://github.com/Chuyu-Team/YY-Thunks" target="_blank" rel="noreferrer">YY-Thunks</a> for the functions the old systems lack. MinGW with libc++ cannot reach XP. The goal is to find out how far hermeticity reaches there; Windows 9x is out of scope.</li><li><strong>msvcrt.</strong> The MinGW targets use UCRT, which is part of Windows 10 and later. A MinGW variant on the older msvcrt is not planned.</li><li><strong>Emscripten.</strong> emsdk is its toolchain, so it is not an xclang target.</li></ul><h2 id="the-xclang-command" tabindex="-1">The xclang Command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang Command&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="xclang-command"></a>The <code>xclang</code> command: <code>xclang sdk fetch</code> for the vendor SDKs</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="target-archives"></a>Target archives and a release index, for <code>xclang target add</code></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="fetched-targets-in-build-systems"></a>Fetched targets and vendor SDKs in the CMake package and the Bazel module</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="msvc-bazel"></a>The MSVC targets in the Bazel module, with the Windows SDK fetched by a repository rule</td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a id="macos-any-host-bazel"></a>macOS targets from Linux and Windows hosts in the Bazel module, with the macOS SDK fetched by a repository rule</td><td><span class="status-badge warn">Unreleased</span></td></tr></tbody></table><p><code>xclang</code> is a program in Rust (<code>cli/</code>), built for every host with xclang as its C compiler and linker. Every toolchain archive carries it, as <code>bin/xclang</code>, since 23.1.2.7 (<a href="./../reference/xclang-command">the xclang command</a>).</p><ul><li><code>xclang sdk fetch</code> downloads a vendor SDK from the vendor, by version and sha256, once the user accepts its license. It is in every release since 23.1.2.7.</li><li><code>xclang target add</code> unpacks a target&#39;s archive of the same release into the toolchain: its sysroot, its runtimes, compiler-rt, its config files and the licenses of its C runtime. No release publishes target archives yet, so it has nothing to add.</li><li>Each release gets an index of its target archives, as rustup&#39;s channel manifests are: archive, sha256, size, tier and the SDK it needs.</li><li>The CMake package and the Bazel module take fetched targets as they come. Today their toolchains build for the six targets of the host&#39;s archive, and the CMake package also for the MSVC targets, and for macOS from Linux and Windows hosts, with the fetched SDKs.</li><li>The plan for the MSVC targets in the Bazel module: a repository rule fetches the Windows SDK once the user accepts its license in <code>MODULE.bazel</code>, and the targets build with the GNU-style clang of the other toolchains.</li><li>The plan for macOS from Linux and Windows hosts in the Bazel module: the same repository rule fetches the macOS SDK, which stands in for the one a macOS host&#39;s rule finds with <code>xcrun</code>, and the macOS toolchains are registered on every host.</li></ul><h2 id="runtimes-and-tools" tabindex="-1">Runtimes and Tools <a class="header-anchor" href="#runtimes-and-tools" aria-label="Permalink to &quot;Runtimes and Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="libc-on-demand"></a>libc++, libc++abi and libunwind built from source on demand</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="msan"></a>MemorySanitizer, through libc++ built on demand</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="mingw-sanitizers"></a>Sanitizers for MinGW targets</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="musl-sanitizers"></a>ASan, TSan, LSan and libFuzzer for musl targets, with a dynamically linked musl (Alpine&#39;s way)</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="bazel-gsymutil"></a><code>@xclang//bazel:llvm-gsymutil</code>, the toolchain&#39;s llvm-gsymutil for <code>bazel run</code></td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="cargo-helper"></a>An <code>xclang cargo</code> helper that sets cargo&#39;s variables</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="libgcc-s-script"></a><code>libgcc_s.a</code> as a linker script naming libunwind, for Rust&#39;s Linux targets</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="libcxx-msvc"></a>libc++ as the C++ library of MSVC targets</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="openmp"></a>An OpenMP runtime</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="tool-binaries"></a>clang-format, clang-tidy and clangd programs</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="shared-runtime"></a>A shared C++ runtime across shared libraries</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="conda-forge"></a>A compiler for building conda-forge packages</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="libclang-msvc"></a>libclang for programs built with the MSVC ABI</td><td><span class="status-badge off">Not planned</span></td></tr></tbody></table><p><strong>libc++ built on demand</strong> means libc++, libc++abi and libunwind built from source inside a CMake or Bazel build, from LLVM&#39;s runtime sources of the release, with its <a href="./../reference/patches">patches</a>. It covers what the prebuilt runtimes cannot be:</p><ul><li><strong>MemorySanitizer</strong>, which needs every library instrumented, libc++ too. ThreadSanitizer also reports better through an instrumented libc++.</li><li><strong>Hardening and ABI options</strong>: a hardening mode checked inside the library, libc++&#39;s ABI version 2, bounded iterators, an ABI namespace of one&#39;s own, and builds without exceptions or RTTI.</li><li><strong>LTO and PGO</strong> of libc++ together with the program.</li><li><strong>Targets without prebuilt runtimes</strong>: tier 3 ones and Apple&#39;s devices.</li></ul><p>The prebuilt runtimes stay the default.</p><p>Rust and cargo work with xclang today as a recipe of environment variables (<a href="./../integrations/cargo">Rust and Cargo</a>). A helper that sets them, as cargo-zigbuild&#39;s wrapper does, is considered. So is making <code>libgcc_s.a</code> a linker script, <code>INPUT(-lunwind)</code>, instead of an empty archive: Rust&#39;s Linux targets then link without <code>-l:libunwind.a</code>. A test with 23.1.2.5&#39;s arm64 sysroot linked Rust, and C++ programs and shared libraries that name <code>-lgcc_s</code>.</p><p><strong>Sanitizers for musl targets</strong> beyond UBSan need dynamic linking: ASan, TSan and LSan find the C library&#39;s functions they intercept through <code>dlsym</code>, which a static program has not, and their runtimes do not link into one. A variant of the musl targets with musl&#39;s <code>libc.so</code>, as Alpine links, would have them, and its programs would need musl on the machine (<a href="./../features/sanitizers#musl-targets">sanitizers</a>).</p><p><strong>libc++ for MSVC targets</strong> gives them the C++ library of every other target, its <code>import std</code> included, and becomes their default. Microsoft&#39;s STL stays a choice: C++ types passed between a program and libraries built with MSVC need the same library on both sides.</p><p>The not-planned items follow from what xclang is. It is a compiler toolchain, and libclang has the libraries that tools on clang link. Its runtimes are linked into every program (<a href="./hermeticity#one-libc-per-shared-object">one libc++ per shared object</a>). conda-forge&#39;s compilers link packaged runtimes dynamically, which xclang does not do. libclang is there for clice, which builds for MinGW on Windows, so no libclang is built with the MSVC ABI.</p><h2 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="pgo-training"></a>A PGO training that covers Objective-C, clang-cl, Mach-O links and clang-tidy&#39;s checks</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="bolt"></a>BOLT for the Linux hosts&#39; clang and lld, on top of PGO and ThinLTO</td><td><span class="status-badge note">In research</span></td></tr></tbody></table><p>The training is widened between releases, not while one is pending (<a href="./pgo#the-training">PGO</a>).</p><h2 id="reproducibility-and-supply-chain" tabindex="-1">Reproducibility and Supply Chain <a class="header-anchor" href="#reproducibility-and-supply-chain" aria-label="Permalink to &quot;Reproducibility and Supply Chain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="cmake-relative-paths"></a>Relative paths in the debug information of CMake builds</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="gsym-determinism"></a>The same GSYM file on every run (<code>xclang_debug_symbols</code> passing <code>--num-threads=1</code>)</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="immutable-releases"></a>Immutable GitHub releases</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="reproducible-archives"></a>Reproducible release archives</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="license-notices"></a>Third-party license notices in the archives</td><td><span class="status-badge ok">Supported</span></td></tr><tr><td><a id="slsa"></a>SLSA provenance attestations</td><td><span class="status-badge note">Considered</span></td></tr></tbody></table><ul><li><strong>CMake builds</strong> write the build tree&#39;s absolute paths into debug information. Bazel builds already use paths relative to the execution root (<a href="./../features/debugging#paths-in-debug-information">debugging</a>).</li><li><strong>GSYM files</strong> from llvm-gsymutil&#39;s default threads differ run to run, with the same lookups. One thread is deterministic, about 1.4 times as slow; <code>xclang_debug_symbols</code> passes <code>--num-threads=1</code> by default since 23.1.2.7.</li><li><strong>Immutable releases</strong> keep an archive and its <code>SHA256SUMS</code> from being replaced together (<a href="./../reference/releases#checking-a-download">releases</a>).</li><li><strong>Reproducible archives</strong>, since 23.1.2.7: sorted entries, the commit&#39;s time and no owner in the <code>.tar.xz</code> files, xz in fixed blocks whatever its threads; each host&#39;s archives are made twice, on two machines, and compared (<a href="./../dev/release-build#the-stages">build</a>). The toolchain builds themselves are not compared.</li><li><strong>License notices</strong>, since 23.1.2.7: every archive has <code>share/licenses</code>, each component&#39;s license files and an SPDX document (<a href="./../reference/layout#licenses">layout</a>).</li></ul><h2 id="following-llvm" tabindex="-1">Following LLVM <a class="header-anchor" href="#following-llvm" aria-label="Permalink to &quot;Following LLVM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="llvm-releases"></a>LLVM 23.1.3 and 24.x, each as it is released</td><td><span class="status-badge note">Planned</span></td></tr></tbody></table><p>Each LLVM release is built with the <a href="./../reference/patches">patches</a> checked against it. 23.1.3 has the fix for the macOS 27 SDK&#39;s <code>arm64e.x1</code> stubs, which xclang carries as patch 0009 since 23.1.2.6.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="zh-docs"></a>The docs in Chinese</td><td><span class="status-badge note">Planned</span></td></tr></tbody></table><p>The docs are in English only for now. The README has a Chinese version.</p><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><p>Questions inside the items above, not items of their own:</p><ul><li><strong>Android&#39;s sysroot</strong>: fetched by the user from Google&#39;s NDK (only the files it needs), or redistributed by xclang.</li><li><strong>The runtimes of Apple&#39;s devices</strong>: published prebuilt, or only built on demand. Apple&#39;s license treats libraries for those platforms apart from macOS ones.</li><li><strong>A glibc other than 2.17</strong>: chosen with a named config file (<code>--config=</code>), or with a spelling of the target.</li><li><strong>Where fetched targets go</strong>: into the toolchain directory only, or also into a directory of the user&#39;s.</li></ul>',41)])])}const u=e(n,[["render",r]]);export{g as __pageData,u as default};
